import React, { useState, useEffect } from 'react';
import axios from 'axios'; // Import axios for making API calls
import './Dashboard.css';

const Dashboard = () => {
  const [coaches, setCoaches] = useState([]); // State to store the list of coaches
  const [gymStats, setGymStats] = useState({});
  const [upcomingClasses, setUpcomingClasses] = useState([]);

  // Fetch all coaches, gym stats, and upcoming classes on mount
  useEffect(() => {
    async function fetchData() {
      try {
        // Fetch coaches
        const coachesRes = await axios.get('/api/coaches', {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`, // Use token if necessary
          },
        });
        setCoaches(coachesRes.data); // Set the fetched coaches data
        
        // Fetch gym stats and upcoming classes (example)
        const statsRes = await axios.get('/api/gym/stats');
        const classesRes = await axios.get('/api/gym/upcomingClasses');
        setGymStats(statsRes.data);
        setUpcomingClasses(classesRes.data);
      } catch (err) {
        console.error('Error fetching data:', err);
      }
    }
    fetchData();
  }, []);

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h2>Welcome to the Dashboard!</h2>
        <p>Manage gym activities, check stats, view coaches, and upcoming classes.</p>
      </header>

      <div className="dashboard-body">
        <div className="dashboard-left">
          {/* Gym Stats */}
          <div className="stats-card">
            <h3>Gym Stats</h3>
            <ul>
              <li>Total Members: {gymStats.totalMembers}</li>
              <li>Active Members: {gymStats.activeMembers}</li>
              <li>Total Classes: {gymStats.totalClasses}</li>
              <li>Upcoming Sessions: {gymStats.upcomingSessions}</li>
            </ul>
          </div>

          {/* Display List of Coaches */}
          <div className="coaches-card">
            <h3>All Coaches</h3>
            <ul>
              {coaches.length === 0 ? (
                <p>No coaches available.</p>
              ) : (
                coaches.map((coach, index) => (
                  <li key={index}>
                    <strong>{coach.name}</strong>
                    <br />
                    <span><strong>Email:</strong> {coach.email}</span>
                    <br />
                    <span><strong>Role:</strong> {coach.role}</span>
                    <br />
                    <span><strong>Experience:</strong> {coach.experience}</span>
                  </li>
                ))
              )}
            </ul>
          </div>
        </div>

        <div className="dashboard-right">
          {/* Upcoming Classes */}
          <div className="classes-card">
            <h3>Upcoming Classes</h3>
            <ul>
              {upcomingClasses.map((classItem, index) => (
                <li key={index}>
                  <strong>{classItem.className}</strong> at {classItem.time} in {classItem.location}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
